export const meta = {
  name: 'criteria-final-judge',
  description: 'Judge-only confirmation pass: 3 independent judges vote on the corrected criteria set to confirm convergence',
  phases: [{ title: 'Final Judge' }],
}

const CONTEXT = `Repos (both owned by valkyriweb): valkyriweb/my-pi (/Users/luke/Projects/personal/my-pi) and valkyriweb/pi-mono fork (/Users/luke/Projects/personal/pi-mono-fork). The fork is checked out on the #75 branch with LIVE UNCOMMITTED work that must never be touched — all code work uses git worktrees under /tmp/. Today is 2026-06-16. These criteria were hardened over 3 prior adversarial rounds (0/3 -> 2/3). The ONLY prior blocking objection was that criterion pr75's SHA-validity check was a no-op python3 expression that always exited 0; it has now been replaced with a direct check that flags any cited hex string not resolving to a real commit. You are confirming whether the corrected set is now fully sound.`

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['accept', 'perCriterion', 'blocking'],
  properties: {
    accept: { type: 'boolean', description: 'true only if you would personally sign off on the WHOLE set as sound, verifiable, measured, safe, and achievable this session' },
    perCriterion: { type: 'array', items: {
      type: 'object',
      required: ['id', 'accept', 'reason'],
      properties: { id: { type: 'string' }, accept: { type: 'boolean' }, reason: { type: 'string' } },
    } },
    blocking: { type: 'array', items: { type: 'string' }, description: 'specific changes still required; empty iff accept=true' },
    pr75ShaCheckVerdict: { type: 'string', description: 'specifically: is the corrected pr75 SHA-validity check now correct and non-gameable?' },
  },
}

const judgePrompt = (i) => `You are independent judge #${i + 1} confirming a set of success criteria for PR/issue cleanup work. Read the full criteria set from the file /Users/luke/Projects/personal/my-pi/.. — actually read it from: /tmp/criteria-fixed.json (a JSON array of {id,item,outcome,verify,measure,outOfScope}). Use the Read tool on /tmp/criteria-fixed.json.

${CONTEXT}

Accept the set ONLY if you would personally sign off: every criterion is mechanically verifiable, measured with a real threshold, safe (no irreversible/external/destructive action beyond the single authorized pr68 push; no risk to the live pi-mono #75 working tree), not gameable, and achievable this session — and the set has no important gap. Pay special attention to whether the corrected pr75 SHA-validity check is now genuinely correct (it should flag any cited hex string that does not resolve to a real commit via git rev-parse --verify). Judge independently. Return your structured verdict; if you do not accept, list the specific blocking changes.`

const judges = (await parallel([0, 1, 2].map((i) => () =>
  agent(judgePrompt(i), { label: `final-judge:${i + 1}`, phase: 'Final Judge', schema: JUDGE_SCHEMA })
))).filter(Boolean)

const yes = judges.filter((j) => j.accept).length
return { accept: `${yes}/${judges.length}`, converged: judges.length === 3 && yes === 3, judges }

export const meta = {
  name: 'criteria-execution',
  description: 'Execute the 6 converged executable criteria, each agent following its exact verify/measure spec in isolated worktrees under global safety invariants; returns structured pass/blocked evidence',
  phases: [
    { title: 'Execute: local-safe', detail: 'pr211, pr75 review, park plans — no external mutation' },
    { title: 'Execute: mutations', detail: 'dedup (close #185), pr68 (push+CI), issues (close+comment)' },
  ],
}

const INVARIANTS = `GLOBAL SAFETY INVARIANTS (violating any is an automatic fail — report status "blocked" instead):
1. NEVER touch the working tree of /Users/luke/Projects/personal/pi-mono-fork — it holds the maintainer's LIVE uncommitted #75 work. No edits, no stash, no checkout, no rebase, no commit there. Read-only git commands (show/log/diff/status) are fine.
2. Session-created git worktrees go ONLY under /tmp/. Exception: the dedup criterion REUSES the pre-existing worktree at /Users/luke/Projects/personal/worktrees/my-pi-provider-family-reload (do not 'git worktree add' that branch — it will fail).
3. The ONLY authorized remote push this whole session is 'git push --force-with-lease origin ci/upstream-sync' on valkyriweb/pi-mono, performed solely by the pr68 criterion. No other push to any remote. NEVER run 'gh pr merge'. NEVER publish a release.
4. If a 'git rebase' exits non-zero (conflict), run 'git rebase --abort' immediately, write the conflicted paths to /tmp/rebase-conflicts-<id>.txt, and report status "blocked" — do NOT force-resolve conflicts.
5. Run every VERIFY step from the criterion literally and capture exit codes / command output as evidence. cwd-sensitive gate commands must be a single shell chain (cd <worktree> && ls <relative-file> && npm run ...).
6. Apply code-craft (clear naming, minimal surgical diffs, no noise) to any code or prose you produce.
Today is 2026-06-16. Both repos are owned by valkyriweb.`

const SPEC_SOURCE = `Your criterion's exact OUTCOME / VERIFY / MEASURE / OUT-OF-SCOPE is in the JSON file /tmp/criteria-fixed.json (an array of {id,...}) and mirrored in /Users/luke/Projects/personal/my-pi/plans/orientation-outcomes.md. READ the file and locate your criterion by id. Follow its VERIFY steps exactly; your job is to make its MEASURE pass (or report blocked with evidence).`

const EXEC_SCHEMA = {
  type: 'object',
  required: ['id', 'status', 'evidence', 'measureChecks'],
  properties: {
    id: { type: 'string' },
    status: { type: 'string', enum: ['met', 'blocked', 'partial'] },
    measureChecks: { type: 'array', description: 'one entry per MEASURE assertion', items: {
      type: 'object',
      required: ['check', 'passed'],
      properties: { check: { type: 'string' }, passed: { type: 'boolean' }, observed: { type: 'string' } },
    } },
    evidence: { type: 'array', items: { type: 'string' }, description: 'key command outputs / exit codes proving the measure' },
    mutationsPerformed: { type: 'array', items: { type: 'string' }, description: 'external/state mutations: commits, pushes, issue closes, comments' },
    blockers: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
}

const codeBrief = `Use the code-craft standard for any code you write or port: clear names, minimal surgical diff, no incidental reformatting, match surrounding style.`
const reviewBrief = `Produce a genuine senior-level review: read the actual diff, reason about correctness and hot-path risk, cite file:line. You may run the autoreview helper at /Users/luke/.claude/skills/autoreview/scripts/autoreview (e.g. --mode branch --base origin/main from a read-only checkout) to enrich findings, but the written review and its file:line citations are the deliverable.`

const prompt = (id, extra) => `You are executing success criterion "${id}" from a converged, adversarially-reviewed criteria set. ${SPEC_SOURCE}

${INVARIANTS}

${extra}

Execute now. Be rigorous and honest: only report status "met" if every MEASURE assertion for "${id}" genuinely passes with captured evidence. If a precondition fails or a rebase conflicts, report "blocked" with the specific reason and any /tmp/ artifact you wrote. Return the structured result.`

// Wave A: local-only, no external mutation — safe to fully parallelize
const waveA = [
  () => agent(prompt('pr211', codeBrief), { label: 'exec:pr211', phase: 'Execute: local-safe', schema: EXEC_SCHEMA }),
  () => agent(prompt('pr75', reviewBrief), { label: 'exec:pr75', phase: 'Execute: local-safe', schema: EXEC_SCHEMA }),
  () => agent(prompt('park', codeBrief), { label: 'exec:park', phase: 'Execute: local-safe', schema: EXEC_SCHEMA }),
]
// Wave B: external state mutations (disjoint objects — parallel-safe, verified afterward)
const waveB = [
  () => agent(prompt('dedup', codeBrief + ' This criterion may CLOSE issue #185 — but only via its step-5 safety net (only if #200 is not CONFLICTING); otherwise leave a holding comment. Capture gate exit codes to /tmp/ before any close.'), { label: 'exec:dedup', phase: 'Execute: mutations', schema: EXEC_SCHEMA }),
  () => agent(prompt('pr68', codeBrief + ' This criterion performs the session\'s ONLY authorized push (origin/ci/upstream-sync, --force-with-lease) and triggers ci.yml. The branch is ~93 commits behind main; if the rebase conflicts, abort+document+blocked.'), { label: 'exec:pr68', phase: 'Execute: mutations', schema: EXEC_SCHEMA }),
  () => agent(prompt('issues', 'This criterion CLOSES 4 duplicate my-pi issues (#113→#134, #118→#120, #109→#110, issue #81→#78) with a pointer comment + duplicate label, and posts CLOSE/KEEP evaluation comments on #2/#3/#4 (default KEEP; close only with a linked merged PR URL). Canonical issues stay OPEN.'), { label: 'exec:issues', phase: 'Execute: mutations', schema: EXEC_SCHEMA }),
]

const results = (await parallel([...waveA, ...waveB])).filter(Boolean)
return { results }

